export const queryElements = async (
    api: Api,
    abortController: AbortController | undefined,
    conversationMode: boolean,
    payload: QueryParams
): Promise<QueryResults> => {
    abortController?.abort();
    const newAbortController = new AbortController();
    const query = conversationMode ? queryConversations : queryMessageMetadata;

    const result: any = await api({ ...query(payload as any), signal: newAbortController.signal });

    return {
        abortController: newAbortController,
        Total: result.Total,
        Elements: conversationMode ? result.Conversations : result.Messages,
        Stale: result.Stale,
        TasksRunning: result.TasksRunning,
    };
};

/**
 * A retry is the same request as before expecting a different result
 * @param payload: request params + expected total
 * @param error: optional error from last request
 */
export const newRetry = (retry: RetryData, payload: any, error: Error | undefined) => {
    const count = error && isDeepEqual(payload, retry.payload) ? retry.count + 1 : 1;
    return { payload, count, error };
};

export const queryElement = async (api: Api, conversationMode: boolean, elementID: string): Promise<Element> => {
    const query = conversationMode ? getConversation : getMessage;
    const result: any = await api({ ...query(elementID), silence: true });
    return conversationMode ? result.Conversation : result.Message;
};

export const refreshTaskRunningTimeout = (
    newLabelIDs: string[],
    {
        getState,
        api,
        dispatch,
        call,
    }: { getState: () => unknown; api: Api; dispatch: (action: any) => void; call: () => Promise<void> }
): NodeJS.Timeout | undefined => {
    let timeoutID: NodeJS.Timeout | undefined = (getState() as RootState).elements.taskRunning.timeoutID;

    if (timeoutID) {
        clearTimeout(timeoutID);
        timeoutID = undefined;
    }

    if (newLabelIDs.length > 0) {
        timeoutID = setTimeout(() => {
            void dispatch(pollTaskRunning({ api, call }));
        }, TASK_RUNNING_POLLING_INTERVAL);
    }

    return timeoutID;
};

import { MARK_AS_STATUS } from '../../hooks/actions/useMarkAs';
import { Element } from '../../models/element';
import { optimisticMarkAs, reset } from './elementsActions';
import elementsReducer from './elementsSlice';

describe('optimistic mark-as bypass filtering', () => {
    const message = { ID: 'message-1', ConversationID: 'conversation-1' } as Element;
    const otherMessage = { ID: 'message-2', ConversationID: 'conversation-2' } as Element;

    it.each([
        { unreadFilter: 1, bypassStatus: MARK_AS_STATUS.READ, matchingStatus: MARK_AS_STATUS.UNREAD },
        { unreadFilter: 0, bypassStatus: MARK_AS_STATUS.UNREAD, matchingStatus: MARK_AS_STATUS.READ },
    ])(
        'removes stale message bypass IDs when the status matches filter $unreadFilter',
        ({ unreadFilter, bypassStatus, matchingStatus }) => {
            let state = elementsReducer(undefined, reset({ params: { filter: { Unread: unreadFilter } } }));

            state = elementsReducer(
                state,
                optimisticMarkAs({ elements: [message, otherMessage], bypass: true, markAsStatus: bypassStatus })
            );
            expect(state.bypassFilter).toEqual(['message-1', 'message-2']);

            state = elementsReducer(
                state,
                optimisticMarkAs({ elements: [message], bypass: true, markAsStatus: matchingStatus })
            );
            expect(state.bypassFilter).toEqual(['message-2']);
        }
    );

    it('uses conversation IDs to add and remove bypasses in conversation mode', () => {
        let state = elementsReducer(undefined, reset({ params: { filter: { Unread: 1 } } }));

        state = elementsReducer(
            state,
            optimisticMarkAs({
                elements: [message],
                bypass: true,
                conversationMode: true,
                markAsStatus: MARK_AS_STATUS.READ,
            })
        );
        expect(state.bypassFilter).toEqual(['conversation-1']);

        state = elementsReducer(
            state,
            optimisticMarkAs({
                elements: [message],
                bypass: true,
                conversationMode: true,
                markAsStatus: MARK_AS_STATUS.UNREAD,
            })
        );
        expect(state.bypassFilter).toEqual([]);
    });
});
